<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,type Website} from '../services/api'
import {useSession} from '../stores/session'
import Notice from './Notice.vue'
const s=useSession(),sites=ref<Website[]>([]),members=ref<{user_id:number;email:string;role:string}[]>([]),name=ref('Mosfix'),origin=ref('https://mosfix.jaimeberrios.com'),error=ref(''),busy=ref(false)
async function load(){const id=s.tenant!.tenant_id;members.value=await api.members(id);if(s.tenant!.role!=='agent')sites.value=await api.websites(id)}
async function run(action:()=>Promise<unknown>){busy.value=true;error.value='';try{await action();await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>run(load))
</script>
<template><section class="card padded"><h2>Miembros y roles</h2><Notice v-if="error" error>{{error}}</Notice><div v-for="m in members" :key="m.user_id" class="admin-row"><span>{{m.email}}</span><select v-if="s.tenant?.role==='owner'&&m.role!=='owner'" :value="m.role" :disabled="busy" :aria-label="`Rol de ${m.email}`" @change="run(()=>api.memberRole(s.tenant!.tenant_id,m.user_id,($event.target as HTMLSelectElement).value))"><option value="agent">Agente</option><option value="admin">Administrador</option></select><span v-else class="chip">{{m.role}}</span></div><p class="caption">El propietario puede cambiar roles de miembros existentes. El alta de usuarios se realiza con el procedimiento administrativo del backend.</p></section><section v-if="s.tenant?.role!=='agent'" class="card padded"><h2>Sitios web</h2><p class="muted">Cada sitio tiene un identificador público y un origen HTTPS autorizado.</p><div v-for="site in sites" :key="site.id" class="website-record"><strong>{{site.name}} · {{site.is_active?'Activo':'Desactivado'}}</strong><p>{{site.origin}}</p><label>ID público<input readonly :value="site.public_id" @focus="($event.target as HTMLInputElement).select()"></label><button v-if="site.is_active" class="button" :disabled="busy" @click="run(()=>api.deactivateWebsite(s.tenant!.tenant_id,site.id))">Desactivar sitio y acceso de visitantes</button></div><form @submit.prevent="run(()=>api.createWebsite(s.tenant!.tenant_id,name,origin))"><label>Nombre<input v-model="name" required maxlength="150"></label><label>Origen autorizado<input v-model="origin" type="url" required maxlength="255" placeholder="https://mosfix.jaimeberrios.com"></label><p class="caption">Sin ruta ni barra final. Guarda el ID público para configurar el widget.</p><button class="button primary" :disabled="busy">Registrar sitio</button></form></section></template>
